ValidationRule.errorConditionFormula:
IF(
  TEXT($UserRole.PortalType) = "CustomerPortal",
  OR(
    AND(
      TEXT(CGD_Agent_Category__c) = "Account Visit",
      OR(
        ISBLANK(CGD_Account__c),
        NOT(ISBLANK(CGD_Account_Code__c))
      )
    ),
    AND(
      TEXT(CGD_Agent_Category__c) = "Prospecting Visit",
      OR(
        ISBLANK(CGD_Account_Code__c),
        NOT(ISBLANK(CGD_Account__c))
      )
    )
  ),
  false
)
